      return {
        refHour,
        localMinutes,
        localHour,
        dayShift: Math.floor(absolute / MINUTES_PER_DAY),
        awake: isAwakeAt(localHour, window),
        state: 'sleeping' as const,
      }
    })
    return { city, isReference: index === 0, offsetMinutes: offsets[index], cells }
  })

