  color: var(--ink);
  font-family: var(--sans);
  font-size: var(--text-base);
  line-height: 1.45;
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}

button,
select,
input {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
}

h1,
p {
  margin: 0;
}

h1 {
  font-size: var(--text-xl);
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.15;
  text-wrap: balance;
}

:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

.shell {
