  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2);
}

.mode-toggle {
  display: inline-flex;
  padding: 3px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius-pill);
}

.mode-toggle button {
