  font-size: var(--text-base);
  line-height: 1.45;
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}

button,
select,
input {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
}

h1,
p {
  margin: 0;
}

h1 {
  font-size: var(--text-xl);
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.15;
  text-wrap: balance;
}

:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

.shell {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  padding: var(--space-4) var(--space-4) var(--space-5);
  gap: var(--space-4);
  max-width: 92rem;
  margin: 0 auto;
}

.topbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3) var(--space-4);
}

.topbar-tools {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2);
}

.mode-toggle {
  display: inline-flex;
  padding: 3px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius-pill);
}

.mode-toggle button {
  appearance: none;
  border: 0;
  background: transparent;
  color: var(--muted);
  padding: 0.35rem 0.85rem;
  border-radius: var(--radius-pill);
  font-size: var(--text-sm);
  font-weight: 500;
  min-height: 2rem;
}

.mode-toggle button.is-on {
  background: var(--primary);
  color: var(--primary-fg);
}

.mode-toggle button:hover:not(.is-on) {
  color: var(--ink);
}

.settings {
