  display: flex;
  justify-content: space-between;
  gap: var(--space-3);
  width: 100%;
  appearance: none;
  border: 0;
  background: transparent;
  text-align: left;
  padding: 0.45rem 0.85rem;
  font-size: var(--text-md);
}

.picker-option.is-active,
.picker-option:hover {
  background: var(--surface);
}

.picker-country {
  color: var(--muted);
  font-size: var(--text-sm);
}

.picker-empty {
  padding: var(--space-4);
  color: var(--muted);
  font-size: var(--text-sm);
}

.main {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  flex: 1;
}

.summary {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2) var(--space-3);
  padding: var(--space-3) var(--space-4);
  background: var(--overlap);
  color: var(--overlap-ink);
  border-radius: var(--radius);
}

.summary-warn {
  background: var(--warning-bg);
  color: var(--warning);
}

.summary-stack {
  background: var(--surface);
  color: var(--ink);
  flex-direction: column;
  align-items: stretch;
  gap: var(--space-3);
}

.summary-quiet {
  font-weight: 400;
  color: inherit;
  opacity: 0.82;
}

.summary-line {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2) var(--space-3);
}

.summary-warn-line {
  color: var(--warning);
}

.range-row {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
}

.range-badge {
  display: inline-flex;
  align-items: center;
  padding: 0.15rem 0.55rem;
  border-radius: var(--radius-pill);
  background: var(--bg);
  color: var(--overlap-ink);
  font-family: var(--mono);
  font-size: var(--text-sm);
  font-weight: 500;
  font-variant-numeric: tabular-nums;
}

.summary-warn .range-badge,
.summary-stack .range-badge {
  background: var(--overlap);
}

.empty {
  padding: var(--space-6);
  text-align: center;
  color: var(--muted);
  background: var(--surface);
  border-radius: var(--radius);
}

.hint {
  font-size: var(--text-sm);
  color: var(--muted);
}

.desktop-grid {
  display: none;
}

.mobile-grid {
  display: block;
}

@media (min-width: 768px) {
  .desktop-grid {
    display: block;
  }

  .mobile-grid {
    display: none;
  }

  .shell {
    padding: var(--space-5) var(--space-5) var(--space-6);
    gap: var(--space-5);
  }
}

.hour-header,
.city-row {
  display: grid;
  grid-template-columns: var(--city-col) minmax(0, 1fr) var(--remove-col);
  align-items: stretch;
  gap: 0;
}

.hour-header {
  margin-bottom: var(--space-1);
}

.desktop-grid {
  overflow-x: auto;
}

.hour-header,
.city-row {
  min-width: 68rem;
}

.hour-header-cells,
.city-row-cells {
  display: grid;
  grid-template-columns: repeat(24, minmax(0, 1fr));
  gap: 1px;
}

.hour-tick {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  min-height: 1.6rem;
  font-family: var(--mono);
  font-size: var(--text-xs);
  font-variant-numeric: tabular-nums;
  color: var(--muted);
}

.hour-tick.is-now {
  color: var(--primary);
  font-weight: 600;
}

.hour-tick-meridiem {
  font-size: 0.5625rem;
  line-height: 1;
}

.city-row {
  margin-bottom: 2px;
}

.city-row.is-ref .city-row-meta {
  background: var(--surface);
}

.city-row-meta {
  display: flex;
  align-items: center;
  padding: 0 var(--space-3) 0 0;
  min-height: 3.25rem;
}

.city-row-action {
  display: flex;
  align-items: center;
  justify-content: center;
}

.city-meta {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.city-meta-top {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  min-width: 0;
}

.city-name {
  appearance: none;
  border: 0;
  background: transparent;
  padding: 0;
  font-weight: 600;
  font-size: var(--text-base);
  text-align: left;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.city-name:hover:not(:disabled) {
  color: var(--primary);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.city-name:disabled {
  cursor: default;
}

.city-meta-sub {
  display: flex;
  gap: var(--space-2);
  font-size: var(--text-xs);
  color: var(--muted);
}

.ref-badge {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.05rem 0.35rem;
  border-radius: var(--radius-sm);
  background: var(--primary);
  color: var(--primary-fg);
  font-size: 0.5625rem;
  font-weight: 700;
  letter-spacing: 0.04em;
}

.city-meta.is-compact {
  align-items: center;
  text-align: center;
}

.city-meta.is-compact .city-meta-top {
  justify-content: center;
  flex-wrap: wrap;
}

.city-meta.is-compact .city-name {
  font-size: var(--text-sm);
}

.city-meta.is-compact .city-meta-sub {
  justify-content: center;
}

.remove-btn {
  appearance: none;
  border: 0;
  background: transparent;
  color: var(--muted);
  width: 2.25rem;
  height: 2.25rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
}

.remove-btn:hover {
  color: var(--ink);
  background: var(--surface);
}

.cell {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 3.25rem;
  min-width: 0;
  padding: 0.15rem 0.05rem;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  font-size: var(--text-xs);
  line-height: 1.1;
  border-radius: 2px;
}

.cell-time {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
}

.cell-hour {
  font-weight: 500;
}

.cell-meridiem {
  font-size: 0.5625rem;
  opacity: 0.8;
}

.cell-shift {
  position: absolute;
  top: 2px;
  right: 3px;
  font-size: 0.5rem;
  font-weight: 600;
  opacity: 0.7;
}

.cell-sleeping {
  background: var(--sleep);
  color: var(--sleep-ink);
}

.cell-awake {
  background: var(--awake);
  color: var(--ink);
  box-shadow: inset 0 0 0 1px var(--line);
}

.cell-overlap {
  background: var(--overlap);
  color: var(--overlap-ink);
}

.cell-overlap .cell-hour {
  font-weight: 700;
}

.cell.is-now {
  box-shadow: inset 0 0 0 1.5px var(--now);
}

.mobile-scroll {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.mobile-table {
  display: grid;
  min-width: 100%;
  gap: 2px;
}

.mobile-corner {
  position: sticky;
  left: 0;
  z-index: 2;
  background: var(--bg);
}

.mobile-hour-label {
  position: sticky;
  left: 0;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding-right: var(--space-2);
  background: var(--bg);
  font-family: var(--mono);
  font-size: var(--text-xs);
  font-variant-numeric: tabular-nums;
  color: var(--muted);
}

.mobile-hour-label.is-now {
  color: var(--primary);
  font-weight: 600;
}

.mobile-city-head {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-1);
  padding: var(--space-2) var(--space-1);
  background: var(--surface);
  border-radius: var(--radius-sm);
  min-height: 5.5rem;
}

.mobile-city-head.is-ref {
  box-shadow: inset 0 0 0 1.5px var(--primary);
}

.mobile-grid .cell {
  min-height: 2.6rem;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition: none !important;
    animation: none !important;
  }
}

@media (max-width: 767px) {
  h1 {
    font-size: var(--text-lg);
  }

  .topbar-tools {
    width: 100%;
  }
}

