  display: flex;
  justify-content: space-between;
  gap: var(--space-3);
  width: 100%;
  appearance: none;
  border: 0;
  background: transparent;
  text-align: left;
  padding: 0.45rem 0.85rem;
  font-size: var(--text-md);
}

.picker-option.is-active,
.picker-option:hover {
  background: var(--surface);
}

.picker-country {
  color: var(--muted);
  font-size: var(--text-sm);
}

.picker-empty {
  padding: var(--space-4);
  color: var(--muted);
  font-size: var(--text-sm);
}

.main {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  flex: 1;
}

