  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 3.25rem;
  min-width: 0;
  padding: 0.15rem 0.05rem;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  font-size: var(--text-xs);
  line-height: 1.1;
  border-radius: 2px;
  overflow: hidden;
}

.cell-time {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
}

.cell-hour {
  font-weight: 500;
}

.cell-meridiem {
  font-size: 0.5625rem;
  opacity: 0.8;
}

.cell-shift {
  position: absolute;
  top: 2px;
  right: 3px;
  font-size: 0.5rem;
  font-weight: 600;
  opacity: 0.7;
}

.cell-sleeping {
  background: var(--sleep);
  color: var(--sleep-ink);
}

.cell-awake {
  background: var(--awake);
  color: var(--ink);
  box-shadow: inset 0 0 0 1px var(--line);
}

.cell-overlap {
  background: var(--overlap);
  color: var(--overlap-ink);
}

.cell-overlap .cell-hour {
  font-weight: 700;
}

.cell.is-now {
  box-shadow: inset 0 0 0 1.5px var(--now);
}

.mobile-scroll {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.mobile-table {
  display: grid;
  min-width: 100%;
  gap: 1px;
}

.mobile-corner {
  position: sticky;
  left: 0;
  z-index: 2;
  background: var(--bg);
}

.mobile-hour-label {
