  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.5rem;
  --space-6: 2rem;

  --radius: 8px;
  --radius-sm: 4px;
  --radius-pill: 999px;

  --city-col: 11.25rem;
  --remove-col: 2.5rem;
  --z-dropdown: 20;

  --ease: cubic-bezier(0.16, 1, 0.3, 1);
  --dur: 180ms;
}

*,
*::before,
