  color: var(--ink);
  font-family: var(--sans);
  font-size: var(--text-base);
  line-height: 1.45;
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}

button,
select,
input {
  font: inherit;
  color: inherit;
}

button {
