  --awake: oklch(0.985 0.008 230);
  --sleep: oklch(0.94 0.01 230);
  --sleep-ink: oklch(0.58 0.02 230);
  --warning: oklch(0.5 0.12 55);
  --warning-bg: oklch(0.96 0.04 55);
  --line: oklch(0.9 0.016 230);
  --now: oklch(0.45 0.086 230);

  --sans: 'IBM Plex Sans', 'Segoe UI', sans-serif;
  --mono: 'IBM Plex Mono', ui-monospace, monospace;

  --text-xs: 0.6875rem;
  --text-sm: 0.75rem;
  --text-md: 0.8125rem;
  --text-base: 0.9375rem;
  --text-lg: 1.125rem;
  --text-xl: 1.5rem;

  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.5rem;
  --space-6: 2rem;

  --radius: 8px;
  --radius-sm: 4px;
  --radius-pill: 999px;

  --city-col: 11.25rem;
  --remove-col: 2.5rem;
  --z-dropdown: 20;

  --ease: cubic-bezier(0.16, 1, 0.3, 1);
  --dur: 180ms;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body,
#root {
